/**
 * Compile-time drift check between the hand-maintained `Database` type and the
 * schema generated from `supabase/migrations`.
 *
 * `database.generated.ts` is committed and regenerated by `pnpm db:types`.
 * `database.ts` stays hand-written because it narrows enum columns to literal
 * unions and marks nullable RPC arguments, which the generator does not
 * express. These assertions make `tsc` fail when a migration adds or removes a
 * table, view, or column without the hand-written type being updated.
 *
 * Scope: names only. Column types and nullability are covered indirectly by the
 * integration suite against the same schema.
 */

import type { Database } from "./database";
import type { Database as GeneratedDatabase } from "./database.generated";

type AssertNever<T extends never> = T;

type HandTables = Database["public"]["Tables"];
type GeneratedTables = GeneratedDatabase["public"]["Tables"];

type MissingTables = Exclude<keyof HandTables, keyof GeneratedTables>;
type ExtraTables = Exclude<keyof GeneratedTables, keyof HandTables>;
type SharedTables = Extract<keyof HandTables, keyof GeneratedTables>;

type MissingColumns = {
  [K in SharedTables]: {
    [C in keyof HandTables[K]["Row"]]: C extends keyof GeneratedTables[K]["Row"]
      ? never
      : `${K & string}.${C & string}`;
  }[keyof HandTables[K]["Row"]];
}[SharedTables];

type ExtraColumns = {
  [K in SharedTables]: {
    [C in keyof GeneratedTables[K]["Row"]]: C extends keyof HandTables[K]["Row"]
      ? never
      : `${K & string}.${C & string}`;
  }[keyof GeneratedTables[K]["Row"]];
}[SharedTables];

export type DatabaseTablesAreInSync = AssertNever<
  MissingTables | ExtraTables | MissingColumns | ExtraColumns
>;

type HandViews = Database["public"]["Views"];
type GeneratedViews = GeneratedDatabase["public"]["Views"];

export type DatabaseViewsAreInSync = AssertNever<
  | Exclude<keyof HandViews, keyof GeneratedViews>
  | Exclude<keyof GeneratedViews, keyof HandViews>
>;

type HandFunctions = Database["public"]["Functions"];
type GeneratedFunctions = GeneratedDatabase["public"]["Functions"];

export type DatabaseFunctionsAreInSync = AssertNever<
  Exclude<keyof HandFunctions, keyof GeneratedFunctions>
>;
